  insert into public.library_item_tags (item_id, tag_id) values
    ('36c4583b-eae8-5a7f-ac72-929c71917419', r_tag_1);
  insert into public.library_item_versions (id, item_id, language_level_id, schema_version, content) values
    ('be4526e4-cc6b-51e1-a2d7-a4d39c5b1ca0', '36c4583b-eae8-5a7f-ac72-929c71917419', null, 1, $lynxpack${"title":"","objective":"Je reconnais les parties d’un texte informatif et je m’en sers pour trouver de l’information.","teacherNote":"Référentiel à construire avec les élèves : afficher d’abord les titres des sections, puis ajouter les points au fil des lectures. Certains documentaires jeunesse disent « sous-titre » plutôt qu’« intertitre »; on peut présenter les deux mots. Les exemples sur la tortue peinte servent seulement à illustrer chaque partie. Revenir au référentiel chaque fois que les élèves cherchent une information dans un texte.","heading":"Les parties qui m’aident à trouver l’information","sections":[{"title":"Le titre","points":["Il annonce le sujet du texte.","Il est placé au début, en gros caractères."],"example":"Avec le titre « La tortue peinte », je sais que le texte parle de cet animal."},{"title":"Les intertitres","points":["Ils séparent le texte en parties.","Chaque intertitre annonce ce que dit la partie qui le suit.","Je les lis pour trouver vite l’information que je cherche."],"example":"« Son habitat », « Son alimentation », « Ses petits »"},{"title":"Les photos et les illustrations","points":["Elles montrent à quoi ressemble ce dont parle le texte.","Je les observe avant de lire pour prédire ce que je vais apprendre."],"example":""},{"title":"Les légendes","points":["Une légende est une courte phrase placée près d’une photo ou d’une illustration.","Elle explique ce que l’image montre."],"example":"Une tortue peinte se réchauffe au soleil sur un tronc d’arbre."},{"title":"Les mots en caractères gras et le glossaire","points":["Les mots importants sont parfois écrits en caractères gras.","Le glossaire, à la fin du texte, explique le sens de ces mots.","Quand je ne comprends pas un mot en caractères gras, je le cherche dans le glossaire."],"example":"Le mot « carapace » est en caractères gras; le glossaire explique que c’est la partie dure qui protège le corps de la tortue."},{"title":"La table des matières","points":["Elle se trouve souvent au début du livre.","Elle donne la liste des parties du livre avec leur numéro de page.","Elle m’aide à aller directement à la bonne page."],"example":""}],"visualIdeas":["Coller près de chaque section un exemple découpé dans une vieille revue ou photocopié d’un documentaire, avec la partie encerclée.","Donner une couleur à chaque partie (par exemple, le titre en rouge et les intertitres en bleu), puis utiliser les mêmes couleurs quand les élèves surlignent un texte.","Laisser de l’espace pour que les élèves ajoutent des exemples trouvés dans leurs lectures."]}$lynxpack$::jsonb);
  perform app.library_refresh_search('36c4583b-eae8-5a7f-ac72-929c71917419');

