  insert into public.library_item_versions (id, item_id, language_level_id, schema_version, content) values
    ('1c2d3f94-8bb6-5fc9-bf1c-8d7946f35bda', 'c0e35266-488b-5d44-8f5a-2437dd31e8e3', null, 1, $lynxpack${"title":"","objective":"J’établis des liens entre les fractions et les nombres décimaux (dixièmes et centièmes) à l’aide de l’argent.","teacherNote":"Les montants des questions sont les mêmes dans toutes les versions : seuls la langue et les appuis changent, et la version enrichie ajoute deux défis. Au Canada, la pièce de 1 ¢ n’est plus fabriquée depuis 2012 ni distribuée depuis 2013, mais les prix et les paiements électroniques s’écrivent encore au cent près : le cent sert ici d’unité de mesure. Les questions 8 et 9 se corrigent à la main.","instructions":"Dans cette fiche, un dollar représente un tout. Lis le rappel, puis réponds aux questions.","text":"Rappel : il faut 10 pièces de 10 ¢ pour faire 1 $. Une pièce de 10 ¢ vaut donc un dixième de dollar : 1/10 de dollar = 0,10 $.\n\nIl faut 100 cents pour faire 1 $. Un cent vaut donc un centième de dollar : 1/100 de dollar = 0,01 $.\n\nDans 0,37 $, le 3 est à la position des dixièmes (3 dixièmes = 30 ¢) et le 7 est à la position des centièmes (7 centièmes = 7 ¢).","glossary":[{"term":"un dixième","definition":"Une des 10 parties égales d’un tout (1/10 = 0,1)."},{"term":"un centième","definition":"Une des 100 parties égales d’un tout (1/100 = 0,01)."},{"term":"un nombre décimal","definition":"Un nombre écrit avec une virgule, comme 0,45."}],"questions":[{"id":"q1","kind":"matching","prompt":"Associe chaque montant à la fraction de dollar qui lui correspond. Une fraction est de trop.","hint":"","points":null,"category":"connaissance","left":[{"id":"l1","text":"0,10 $"},{"id":"l2","text":"0,25 $"},{"id":"l3","text":"0,50 $"},{"id":"l4","text":"0,01 $"}],"right":[{"id":"r1","text":"1/2"},{"id":"r2","text":"1/100"},{"id":"r3","text":"1/10"},{"id":"r4","text":"1/4"},{"id":"r5","text":"1/5"}]},{"id":"q2","kind":"short_answer","prompt":"Combien de pièces de 10 ¢ faut-il pour faire 0,70 $?","hint":"","points":null,"category":"connaissance","lines":1},{"id":"q3","kind":"short_answer","prompt":"Écris 45 centièmes de dollar sous forme de nombre décimal.","hint":"","points":null,"category":"connaissance","lines":1},{"id":"q4","kind":"multiple_choice","prompt":"Coche toutes les fractions de dollar qui valent 0,30 $.","hint":"","points":null,"category":"habiletes","choices":[{"id":"a","text":"3/10"},{"id":"b","text":"3/100"},{"id":"c","text":"30/100"},{"id":"d","text":"1/3"}],"multipleAnswers":true},{"id":"q5","kind":"true_false","prompt":"0,5 $ et 0,50 $ représentent le même montant.","hint":"","points":null,"category":"connaissance"},{"id":"q6","kind":"true_false","prompt":"0,09 $ est plus grand que 0,10 $.","hint":"","points":null,"category":"habiletes"},{"id":"q7","kind":"ordering","prompt":"Place ces montants du plus petit au plus grand.","hint":"","points":null,"category":"connaissance","items":[{"id":"a","text":"0,75 $"},{"id":"b","text":"0,07 $"},{"id":"c","text":"0,57 $"},{"id":"d","text":"0,70 $"}]},{"id":"q8","kind":"short_answer","prompt":"Capucine a 3 pièces de 25 ¢ et 2 pièces de 10 ¢. Quelle fraction de dollar a-t-elle? Écris ta réponse en centièmes, puis sous forme de nombre décimal.","hint":"","points":null,"category":"application","lines":2},{"id":"q9","kind":"short_answer","prompt":"Bastien dit que 0,4 $, c’est 4 cents. Explique son erreur.","hint":"","points":null,"category":"communication","lines":3}],"visualSupports":["Des pièces de monnaie de jeu (10 ¢, 25 ¢ et 1 $) pour manipuler les montants.","Une grille de 100 cases où chaque case vaut 1 ¢ et chaque rangée de 10 cases vaut 10 ¢.","Un tableau de valeur de position avec les colonnes « unités », « dixièmes » et « centièmes »."]}$lynxpack$::jsonb),
    ('3ae7c393-b28d-5c1c-bce3-6dcef63ba4ce', 'c0e35266-488b-5d44-8f5a-2437dd31e8e3', r_level_1, 1, $lynxpack${"title":"","objective":"J’établis des liens entre les fractions et les nombres décimaux (dixièmes et centièmes) à l’aide de l’argent.","teacherNote":"Version Débutant : rappel en phrases très courtes, exemples, indices et glossaire. Mêmes montants que les autres versions. Faire manipuler de la monnaie de jeu au besoin.","instructions":"Un dollar = un tout. Lis le rappel. Ensuite, réponds aux questions.","text":"Rappel : 1 $ = 10 pièces de 10 ¢. Une pièce de 10 ¢ = 1/10 de dollar = 0,10 $.\n\n1 $ = 100 ¢. 1 ¢ = 1/100 de dollar = 0,01 $.\n\nExemple : 0,37 $. Le 3 est aux dixièmes : 30 ¢. Le 7 est aux centièmes : 7 ¢.","glossary":[{"term":"un dixième","definition":"Une partie sur 10 (1/10)."},{"term":"un centième","definition":"Une partie sur 100 (1/100)."},{"term":"un cent","definition":"Un centième de dollar (1 ¢)."},{"term":"un nombre décimal","definition":"Un nombre avec une virgule, comme 0,45."},{"term":"une pièce","definition":"Une pièce de monnaie, comme une pièce de 10 ¢."}],"questions":[{"id":"q1","kind":"matching","prompt":"Relie chaque montant à la bonne fraction de dollar. Une fraction est de trop.","hint":"1 $ = 100 ¢.","points":null,"category":"connaissance","left":[{"id":"l1","text":"0,10 $"},{"id":"l2","text":"0,25 $"},{"id":"l3","text":"0,50 $"},{"id":"l4","text":"0,01 $"}],"right":[{"id":"r1","text":"1/2"},{"id":"r2","text":"1/100"},{"id":"r3","text":"1/10"},{"id":"r4","text":"1/4"},{"id":"r5","text":"1/5"}]},{"id":"q2","kind":"short_answer","prompt":"Combien de pièces de 10 ¢ faut-il pour avoir 0,70 $?","hint":"","points":null,"category":"connaissance","lines":1},{"id":"q3","kind":"short_answer","prompt":"Écris 45 centièmes de dollar avec une virgule.","hint":"Un exemple : 30 centièmes de dollar = 0,30 $.","points":null,"category":"connaissance","lines":1},{"id":"q4","kind":"multiple_choice","prompt":"Coche toutes les fractions de dollar égales à 0,30 $.","hint":"Il y a deux bonnes réponses.","points":null,"category":"habiletes","choices":[{"id":"a","text":"3/10"},{"id":"b","text":"3/100"},{"id":"c","text":"30/100"},{"id":"d","text":"1/3"}],"multipleAnswers":true},{"id":"q5","kind":"true_false","prompt":"0,5 $ et 0,50 $ représentent le même montant.","hint":"","points":null,"category":"connaissance"},{"id":"q6","kind":"true_false","prompt":"0,09 $ est plus grand que 0,10 $.","hint":"","points":null,"category":"habiletes"},{"id":"q7","kind":"ordering","prompt":"Place ces montants du plus petit au plus grand.","hint":"Compare d’abord le chiffre des dixièmes.","points":null,"category":"connaissance","items":[{"id":"a","text":"0,75 $"},{"id":"b","text":"0,07 $"},{"id":"c","text":"0,57 $"},{"id":"d","text":"0,70 $"}]},{"id":"q8","kind":"short_answer","prompt":"Capucine a 3 pièces de 25 ¢ et 2 pièces de 10 ¢. Combien de centièmes de dollar a-t-elle? Écris la fraction et le nombre décimal.","hint":"Calcule d’abord le total en cents.","points":null,"category":"application","lines":2},{"id":"q9","kind":"short_answer","prompt":"Bastien dit : « 0,4 $, c’est 4 cents. » Il se trompe. Explique pourquoi.","hint":"","points":null,"category":"communication","lines":3}],"visualSupports":["Des pièces de monnaie de jeu (10 ¢, 25 ¢ et 1 $) pour manipuler les montants.","Une grille de 100 cases où chaque case vaut 1 ¢ et chaque rangée de 10 cases vaut 10 ¢.","Un tableau de valeur de position avec les colonnes « unités », « dixièmes » et « centièmes »."]}$lynxpack$::jsonb),
