  insert into public.library_item_versions (id, item_id, language_level_id, schema_version, content) values
    ('52793685-5ae9-5837-83c0-df350006d9ff', '9f10de3c-3b1e-5110-aebb-c0605e9d0991', null, 1, $lynxpack${"title":"","objective":"J’arrondis des nombres naturels à la dizaine près.","teacherNote":"Billet de sortie pour la fin de la leçon « Arrondir à la dizaine ». Les trois questions et les nombres sont les mêmes dans toutes les versions; seule la langue change. La question 2 vérifie la convention du nombre situé au milieu (365 devient 370). La question 3 se corrige à la main : repérer les élèves qui répondent 90 ou qui ne justifient pas. Voir aussi le guide « Arrondir : idées fausses fréquentes ».","prompt":"Avant de partir, montre ce que tu sais sur l’arrondissement à la dizaine près.","questions":[{"id":"q1","kind":"multiple_choice","prompt":"Arrondis 47 à la dizaine près.","hint":"","points":null,"category":"connaissance","choices":[{"id":"a","text":"40"},{"id":"b","text":"45"},{"id":"c","text":"50"},{"id":"d","text":"100"}],"multipleAnswers":false},{"id":"q2","kind":"short_answer","prompt":"Arrondis 365 à la dizaine près.","hint":"","points":null,"category":"connaissance","lines":1},{"id":"q3","kind":"short_answer","prompt":"Il y a 83 livres dans le bac de lecture. Environ combien de livres y a-t-il, à la dizaine près? Explique comment tu le sais.","hint":"","points":null,"category":"communication","lines":3}]}$lynxpack$::jsonb),
    ('5b643aee-cc8e-5ecd-a607-f7f446a50e9e', '9f10de3c-3b1e-5110-aebb-c0605e9d0991', r_level_1, 1, $lynxpack${"title":"","objective":"J’arrondis des nombres naturels à la dizaine près.","teacherNote":"Version Débutant : consignes très courtes et un indice par question. Mêmes questions et mêmes nombres que les autres versions.","prompt":"Avant de partir, réponds aux trois questions.","questions":[{"id":"q1","kind":"multiple_choice","prompt":"Arrondis 47 à la dizaine près.","hint":"47 est entre 40 et 50. Lequel est le plus proche?","points":null,"category":"connaissance","choices":[{"id":"a","text":"40"},{"id":"b","text":"45"},{"id":"c","text":"50"},{"id":"d","text":"100"}],"multipleAnswers":false},{"id":"q2","kind":"short_answer","prompt":"Arrondis 365 à la dizaine près.","hint":"365 est entre 360 et 370.","points":null,"category":"connaissance","lines":1},{"id":"q3","kind":"short_answer","prompt":"Il y a 83 livres dans le bac. Arrondis 83 à la dizaine près. Dis pourquoi.","hint":"83 est entre 80 et 90.","points":null,"category":"communication","lines":3}]}$lynxpack$::jsonb),
