    ('1096dc54-0914-5bb7-880d-40e06d7dab2a', '9f10de3c-3b1e-5110-aebb-c0605e9d0991', r_level_3, 1, $lynxpack${"title":"","objective":"J’arrondis des nombres naturels à la dizaine près.","teacherNote":"Version Avancé : même billet que la version de base, écrit dans le français attendu en 3e année.","prompt":"Avant de partir, montre ce que tu sais sur l’arrondissement à la dizaine près.","questions":[{"id":"q1","kind":"multiple_choice","prompt":"Arrondis 47 à la dizaine près.","hint":"","points":null,"category":"connaissance","choices":[{"id":"a","text":"40"},{"id":"b","text":"45"},{"id":"c","text":"50"},{"id":"d","text":"100"}],"multipleAnswers":false},{"id":"q2","kind":"short_answer","prompt":"Arrondis 365 à la dizaine près.","hint":"","points":null,"category":"connaissance","lines":1},{"id":"q3","kind":"short_answer","prompt":"Il y a 83 livres dans le bac de lecture. Environ combien de livres y a-t-il, à la dizaine près? Explique comment tu le sais.","hint":"","points":null,"category":"communication","lines":3}]}$lynxpack$::jsonb),
    ('e985df51-3b2c-52e9-b730-0efafa863fe6', '9f10de3c-3b1e-5110-aebb-c0605e9d0991', r_level_4, 1, $lynxpack${"title":"","objective":"J’arrondis des nombres naturels à la dizaine près.","teacherNote":"Version Enrichi : consignes plus précises et justification plus exigeante à la question 3. Mêmes questions et mêmes nombres que les autres versions.","prompt":"Avant de quitter la classe, montre ce que tu as compris de l’arrondissement à la dizaine près.","questions":[{"id":"q1","kind":"multiple_choice","prompt":"Arrondis 47 à la dizaine près.","hint":"","points":null,"category":"connaissance","choices":[{"id":"a","text":"40"},{"id":"b","text":"45"},{"id":"c","text":"50"},{"id":"d","text":"100"}],"multipleAnswers":false},{"id":"q2","kind":"short_answer","prompt":"Arrondis 365 à la dizaine près.","hint":"","points":null,"category":"connaissance","lines":1},{"id":"q3","kind":"short_answer","prompt":"Le bac de lecture contient 83 livres. Environ combien de livres contient-il, à la dizaine près? Justifie ta réponse en comparant les distances.","hint":"","points":null,"category":"communication","lines":3}]}$lynxpack$::jsonb);
  insert into public.library_item_answer_keys (version_id, answer_key) values
    ('52793685-5ae9-5837-83c0-df350006d9ff', $lynxpack${"answers":[{"questionId":"q1","kind":"multiple_choice","correctChoiceIds":["c"],"explanation":"47 est entre 40 et 50. Il est à 3 de 50 et à 7 de 40 : il est plus proche de 50."},{"questionId":"q2","kind":"short_answer","sampleAnswer":"370","acceptableAnswers":["370"],"explanation":"365 est exactement au milieu entre 360 et 370. Par convention, on arrondit vers le haut : 370."},{"questionId":"q3","kind":"short_answer","sampleAnswer":"Environ 80 livres. 83 est entre 80 et 90 : il est à 3 de 80 et à 7 de 90, donc il est plus proche de 80.","acceptableAnswers":[],"explanation":"Correction manuelle : attendre 80 et une justification (distance, droite numérique ou chiffre des unités plus petit que 5)."}],"solution":""}$lynxpack$::jsonb),
