  insert into public.library_item_grades (item_id, grade_code) values
    ('5eef2df6-c4f7-56f6-82cd-1a89d935afd9', '3');
  insert into public.library_item_expectations (item_id, expectation_id) values
    ('5eef2df6-c4f7-56f6-82cd-1a89d935afd9', r_exp_9);
  insert into public.library_item_tags (item_id, tag_id) values
    ('5eef2df6-c4f7-56f6-82cd-1a89d935afd9', r_tag_11), ('5eef2df6-c4f7-56f6-82cd-1a89d935afd9', r_tag_2), ('5eef2df6-c4f7-56f6-82cd-1a89d935afd9', r_tag_5);
  insert into public.library_item_versions (id, item_id, language_level_id, schema_version, content) values
    ('845e902e-9a4c-5848-a288-49792db70076', '5eef2df6-c4f7-56f6-82cd-1a89d935afd9', null, 1, $lynxpack${"title":"","objective":"J’organise mes idées dans un organisateur graphique avant d’écrire une fiche informative sur un animal.","teacherNote":"Ce centre prépare le projet « Mon documentaire sur un animal de l’Ontario ». Choisissez à la bibliothèque des livres documentaires faciles à lire (castor, huard, orignal, tortue peinte, raton laveur, grand héron…). Les élèves qui apprennent le français peuvent dessiner dans les cases, puis écrire un ou deux mots-clés avec l’aide de la banque de mots « Les animaux de l’Ontario ». Avant la rédaction, vérifiez avec chaque élève que les faits notés viennent bien du livre.","setup":"Installez une table pour 4 élèves avec les livres, les feuilles, les crayons et une minuterie réglée à 25 minutes. Lors d’une première visite, montrez en groupe comment plier la feuille en quatre cases et écrire des mots-clés plutôt que des phrases complètes. Affichez au centre les quatre titres des cases : Habitat, Ce qu’il mange, Apparence, Fait étonnant.","groupSize":"4 élèves","studentSteps":["Choisis un livre du centre sur un animal de l’Ontario. Écris le nom de l’animal en haut de ta feuille.","Plie ta feuille en deux, puis encore en deux. Déplie-la : tu as maintenant 4 cases.","Écris un titre dans chaque case : Habitat, Ce qu’il mange, Apparence, Fait étonnant.","Cherche l’information dans le livre. Dans chaque case, écris 2 ou 3 mots-clés, pas des phrases complètes.","Ajoute un petit dessin dans chaque case pour t’aider à te souvenir de tes idées.","Relis tes cases avec la personne à côté de toi. Chaque mot-clé est-il dans la bonne case?","Au bas de ta feuille, écris le titre du livre où tu as trouvé l’information."],"extension":"Choisis ta case la plus intéressante. Transforme tes mots-clés en deux phrases complètes. Commence chaque phrase par une majuscule et termine-la par un point.","cleanup":"Remets les livres dans le bac, range les crayons et dépose ta feuille dans le panier « Mes plans d’écriture »."}$lynxpack$::jsonb);
  perform app.library_refresh_search('5eef2df6-c4f7-56f6-82cd-1a89d935afd9');

