  insert into public.library_item_tags (item_id, tag_id) values
    ('4d133e0c-0b2e-5a0c-b6ad-79e449747640', r_tag_15), ('4d133e0c-0b2e-5a0c-b6ad-79e449747640', r_tag_14), ('4d133e0c-0b2e-5a0c-b6ad-79e449747640', r_tag_13), ('4d133e0c-0b2e-5a0c-b6ad-79e449747640', r_tag_16);
  insert into public.library_item_versions (id, item_id, language_level_id, schema_version, content) values
    ('78df6b36-a4ce-577d-b3bb-cc8d12339015', '4d133e0c-0b2e-5a0c-b6ad-79e449747640', null, 1, $lynxpack${"title":"","objective":"J’explique comment la forme et l’assemblage des matériaux aident une structure à résister aux forces.","teacherNote":"Prévoyez deux périodes : définir, rechercher et planifier la première; construire, tester, améliorer et communiquer la deuxième. Faites un essai avant la leçon, car les résultats dépendent beaucoup du papier et du ruban : une feuille à plat porte à peine une ou deux rondelles, alors qu’un pont bien renforcé en porte souvent plusieurs dizaines (ordre de grandeur à vérifier avec votre matériel). Faites le lien avec l’expérience « Éponges et élastiques » : sous la charge, le dessus du pont est écrasé (compression) et le dessous est étiré (tension).","challenge":"Construis un pont de papier qui franchit un espace de 20 cm entre deux piles de livres. Ton pont doit porter un gobelet placé en son milieu, et on y ajoutera des rondelles une à la fois. Quelle forme donneras-tu au papier pour que ton pont porte le plus de rondelles possible?","constraints":["Tu peux utiliser seulement 10 feuilles de papier et 1 m de ruban-cache.","Le pont doit franchir un espace de 20 cm entre les deux piles de livres.","Le pont repose sur les livres : il ne peut pas y être collé ni attaché.","Le gobelet est posé au milieu du pont.","Vous avez 40 minutes pour construire le pont."],"criteria":["Le pont franchit l’espace de 20 cm sans toucher la table.","Le pont porte le gobelet vide pendant 10 secondes.","L’équipe note le nombre de rondelles portées à chaque essai.","L’équipe explique comment la forme de son pont l’aide à résister à la compression et à la tension.","L’équipe améliore son pont après le premier essai et compare les deux résultats."],"designStages":[{"stage":"definir","prompt":"Explique le défi dans tes mots. Que doit faire le pont? Quelles sont les contraintes?"},{"stage":"rechercher","prompt":"Fais un essai rapide : place entre les livres une feuille à plat, puis une feuille roulée en tube, puis une feuille pliée en accordéon dans le sens de la longueur. Pose une rondelle au milieu de chacune. Laquelle plie le moins?"},{"stage":"planifier","prompt":"Dessine ton pont et nomme les formes que tu utiliseras (tubes, poutres pliées, triangles). Indique par des flèches où le papier sera écrasé et où il sera étiré."},{"stage":"construire","prompt":"Construis ton pont en respectant les contraintes. Assemble les pièces avec le ruban-cache."},{"stage":"tester","prompt":"Pose le gobelet au milieu du pont. Ajoute les rondelles une à la fois jusqu’à ce que le pont cède ou que le gobelet touche la serviette. Note le nombre de rondelles."},{"stage":"ameliorer","prompt":"Trouve l’endroit où ton pont a cédé. Change une seule chose pour le renforcer, puis fais un deuxième essai."},{"stage":"communiquer","prompt":"Présente ton pont à la classe : sa forme, le nombre de rondelles portées aux deux essais et ce que tu as changé."}],"reflectionQuestions":[{"id":"r1","kind":"multiple_choice","prompt":"Tu poses une feuille entre deux livres, puis une charge au milieu. Quelles formes de papier plient le moins? Choisis toutes les bonnes réponses.","hint":"","points":null,"category":"connaissance","choices":[{"id":"a","text":"Une feuille à plat"},{"id":"b","text":"Une feuille roulée en tube serré"},{"id":"c","text":"Une feuille pliée en accordéon dans le sens de la longueur"},{"id":"d","text":"Une feuille froissée en boule"}],"multipleAnswers":true},{"id":"r2","kind":"short_answer","prompt":"Pendant le test, quelle partie de ton pont était écrasée (compression)? Quelle partie était étirée (tension)?","hint":"","points":null,"category":"habiletes","lines":3},{"id":"r3","kind":"short_answer","prompt":"Qu’as-tu changé pour améliorer ton pont? Est-ce que ça a fonctionné? Appuie ta réponse sur les résultats de tes deux essais.","hint":"","points":2,"category":"communication","lines":4},{"id":"r4","kind":"true_false","prompt":"Un pont fait avec plus de papier est toujours plus solide.","hint":"","points":null,"category":"application"}]}$lynxpack$::jsonb);
  insert into public.library_item_answer_keys (version_id, answer_key) values
    ('78df6b36-a4ce-577d-b3bb-cc8d12339015', $lynxpack${"answers":[{"questionId":"r1","kind":"multiple_choice","correctChoiceIds":["b","c"],"explanation":"Le tube et l’accordéon donnent de la hauteur au papier dans le sens de la charge : ils plient beaucoup moins qu’une feuille à plat. Une boule ne peut pas franchir l’espace."},{"questionId":"r2","kind":"short_answer","sampleAnswer":"Le dessus du pont était écrasé (compression) et le dessous était étiré (tension), surtout au milieu, sous le gobelet.","acceptableAnswers":[],"explanation":""},{"questionId":"r3","kind":"short_answer","sampleAnswer":"Nous avons ajouté deux tubes de papier sous le pont, dans le sens de la longueur. Au premier essai, le pont a porté 8 rondelles; au deuxième, il en a porté 23. Les tubes ont rendu le pont plus solide.","acceptableAnswers":[],"explanation":"Évaluer l’usage des résultats des deux essais pour justifier la conclusion."},{"questionId":"r4","kind":"true_false","correct":false,"explanation":"La forme et l’assemblage comptent plus que la quantité de papier : quelques tubes bien placés sont plus solides qu’une pile de feuilles à plat."}],"solution":"Solutions efficaces fréquentes : des tubes roulés serrés ou des poutres pliées en accordéon, en U ou en triangle, placés dans le sens de la longueur sous le tablier. Élargir les appuis sur les livres aide aussi. Sous la charge, le dessus de la poutre est en compression et le dessous en tension; le pont cède souvent au milieu, là où le papier s’écrase ou se déchire."}$lynxpack$::jsonb);
  perform app.library_refresh_search('4d133e0c-0b2e-5a0c-b6ad-79e449747640');

