  insert into public.library_item_grades (item_id, grade_code) values
    ('ec4d954b-6168-535a-8503-92a6c2926e2a', '3');
  insert into public.library_item_expectations (item_id, expectation_id) values
    ('ec4d954b-6168-535a-8503-92a6c2926e2a', r_exp_12);
  insert into public.library_item_tags (item_id, tag_id) values
    ('ec4d954b-6168-535a-8503-92a6c2926e2a', r_tag_11), ('ec4d954b-6168-535a-8503-92a6c2926e2a', r_tag_1), ('ec4d954b-6168-535a-8503-92a6c2926e2a', r_tag_2), ('ec4d954b-6168-535a-8503-92a6c2926e2a', r_tag_5);
  insert into public.library_item_versions (id, item_id, language_level_id, schema_version, content) values
    ('9e4680f7-1dba-5a85-a256-6b0bf10356e4', 'ec4d954b-6168-535a-8503-92a6c2926e2a', null, 1, $lynxpack${"title":"","objective":"Je planifie et j’écris un court texte informatif bien organisé pour présenter un animal de l’Ontario à un public.","teacherNote":"Comptez environ 8 séances de 30 minutes. Public suggéré : une classe de 1re année ou les familles, lors d’une exposition en classe. Le centre « Atelier d’écriture : ma fiche animale » sert à l’étape 2, et la « Grille d’évaluation : la fiche informative » peut servir à évaluer le livret. Avant la mise au propre, vérifiez avec chaque élève les faits trouvés dans des sources fiables. Les élèves qui apprennent le français peuvent présenter avec leurs mots-clés comme aide-mémoire.","drivingQuestion":"Comment présenter un animal de l’Ontario pour que des élèves plus jeunes apprennent des choses vraies et intéressantes?","overview":"Tu vas devenir spécialiste d’un animal de l’Ontario. Tu vas chercher de l’information dans des livres, l’organiser, puis écrire un petit livret documentaire de quatre pages, avec des intertitres, des dessins et des légendes. À la fin, tu présenteras ton documentaire à des élèves plus jeunes.","milestones":[{"title":"Choisir mon animal","description":"Je choisis un animal qui vit en Ontario. J’écris ce que je sais déjà et trois questions que je me pose sur lui.","sessions":1},{"title":"Chercher et organiser","description":"Je cherche des réponses dans des livres documentaires. J’écris des mots-clés dans les quatre cases de ma fiche animale : habitat, alimentation, apparence et fait étonnant.","sessions":2},{"title":"Écrire mon brouillon","description":"Pour chaque case, j’écris un paragraphe de deux ou trois phrases. La première phrase dit de quoi parle le paragraphe.","sessions":1},{"title":"Réviser et corriger","description":"Je relis mon texte avec une ou un camarade. Je remplace un mot vague par un mot précis. Je vérifie les majuscules, les points et les accords.","sessions":1},{"title":"Mettre au propre","description":"Je fabrique mon livret : une couverture avec un titre, puis quatre pages avec un intertitre, mon paragraphe, un dessin et une légende.","sessions":2},{"title":"Présenter","description":"Je présente mon documentaire à des élèves plus jeunes. Je lis une page à voix haute et je réponds à une question.","sessions":1}],"deliverables":["Ma fiche animale remplie avec mes mots-clés","Mon brouillon révisé et corrigé","Mon livret documentaire : une couverture et quatre pages","Ma présentation orale d’environ deux minutes"],"successCriteria":["Mon texte donne des informations vraies sur un animal de l’Ontario.","Chaque page a un intertitre qui annonce son sujet.","Chaque paragraphe contient deux ou trois phrases sur le même sujet.","J’utilise des mots précis, par exemple : herbivore, terrier, plumage.","Mes phrases commencent par une majuscule et se terminent par un point.","Chaque dessin a une légende qui explique ce qu’on voit."]}$lynxpack$::jsonb);
  perform app.library_refresh_search('ec4d954b-6168-535a-8503-92a6c2926e2a');

  -- 15. demo/chasse-aux-nombres (outdoor_activity)
  insert into public.library_items (id, board_id, school_id, type, title, summary, status,
    share_scope, source, author_id, licence, content_pack_id, subject_id, duration_minutes,
    materials, keywords, is_printable, is_projectable, is_interactive, sub_friendly,
    safety_notes, faith_content, faith_on_student_sheet, catholic_connection,
