    ('94b4bf34-c69b-5c0d-b483-883396d8ff1f', '596a42e3-d90e-5b08-87ab-27761527b929', r_level_4, 1, $lynxpack${"title":"","objective":"Je reconnais et je représente des fractions équivalentes à l’aide de modèles et d’une droite numérique.","teacherNote":"Vocabulaire plus précis (représenter, situer, justifier) et une justification plus poussée à la question 3. Les questions, les nombres et les réponses sont les mêmes que dans la version de base.","prompt":"Réponds aux trois questions avant de quitter la classe. Justifie tes réponses avec précision; tu peux t’appuyer sur un modèle, comme une bande de papier ou une droite numérique, esquissé dans la marge.","questions":[{"id":"q1","kind":"multiple_choice","prompt":"Parmi les fractions suivantes, laquelle représente la même quantité que 2/3?","hint":"","points":null,"category":"connaissance","choices":[{"id":"a","text":"4/5"},{"id":"b","text":"4/6"},{"id":"c","text":"2/6"},{"id":"d","text":"3/4"}],"multipleAnswers":false},{"id":"q2","kind":"true_false","prompt":"On plie une bande de papier en quatre parts égales, puis on colorie deux de ces parts. La partie coloriée correspond exactement à la moitié de la bande.","hint":"","points":null,"category":"application"},{"id":"q3","kind":"short_answer","prompt":"Sur une droite numérique graduée en dixièmes, de 0 à 1, Noé situe un point à 4/10. Trouve une fraction équivalente à 4/10 dont le dénominateur est plus petit, puis justifie ta démarche. Explique aussi comment la droite numérique permet de vérifier que les deux fractions désignent le même point.","hint":"","points":null,"category":"habiletes","lines":4}]}$lynxpack$::jsonb);
  insert into public.library_item_answer_keys (version_id, answer_key) values
    ('949f5835-b21b-51a9-bf0f-f51800588380', $lynxpack${"answers":[{"questionId":"q1","kind":"multiple_choice","correctChoiceIds":["b"],"explanation":"2/3 = 4/6 : on multiplie le numérateur et le dénominateur par 2. Le choix 4/5 vient d’une erreur fréquente : ajouter 2 en haut et en bas ne donne pas une fraction équivalente."},{"questionId":"q2","kind":"true_false","correct":true,"explanation":"2 parts sur 4 parts égales, c’est 2/4 de la bande, et 2/4 = 1/2."},{"questionId":"q3","kind":"short_answer","sampleAnswer":"2/5. J’ai divisé le numérateur et le dénominateur par 2 : 4 ÷ 2 = 2 et 10 ÷ 2 = 5. Sur la droite numérique, 4/10 et 2/5 sont au même point.","acceptableAnswers":[],"explanation":"2/5 est la seule réponse possible (dénominateur plus petit que 10). Acceptez toute explication juste : diviser le numérateur et le dénominateur par 2, regrouper les dixièmes deux par deux, plier une bande, situer les deux fractions sur la droite numérique."}],"solution":""}$lynxpack$::jsonb),
